    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def spans(length, separators):
        out, start = [], 0
        for i in separators:
            if start < i:
                out.append((start, i))
            start = i + 1
        if start < length:
            out.append((start, length))
        return out

    row_spans, col_spans = spans(h, sep_rows), spans(w, sep_cols)
    panels = []
    for rs in row_spans:
        for cs in col_spans:
            vals = [grid[r][c] for r in range(*rs) for c in range(*cs)]
            panels.append((sum(v != bg for v in vals), rs, cs))
    _, src_r, src_c = max(panels, key=lambda p: p[0])
    sh, sw = src_r[1] - src_r[0], src_c[1] - src_c[0]
    out = [row[:] for row in grid]
    for rs in row_spans:
        for cs in col_spans:
            if rs[1] - rs[0] == sh and cs[1] - cs[0] == sw:
                for dr in range(sh):
                    for dc in range(sw):
                        out[rs[0] + dr][cs[0] + dc] = grid[src_r[0] + dr][src_c[0] + dc]
